diff --git a/src/compressor.h b/src/compressor.h
index b6b738f654..d252c0b712 100644
--- a/src/compressor.h
+++ b/src/compressor.h
@@ -12,6 +12,8 @@
 #include <serialize.h>
 #include <span.h>

+#include <ios>
+
 /**
  * This saves us from making many heap allocations when serializing
  * and deserializing compressed scripts.
@@ -23,9 +25,9 @@
 using CompressedScript = prevector<33, unsigned char>;


-bool CompressScript(const CScript& script, CompressedScript& out);
+[[nodiscard]] bool CompressScript(const CScript& script, CompressedScript& out);
 unsigned int GetSpecialScriptSize(unsigned int nSize);
-bool DecompressScript(CScript& script, unsigned int nSize, const CompressedScript& in);
+[[nodiscard]] bool DecompressScript(CScript& script, unsigned int nSize, const CompressedScript& in);

 /**
  * Compress amount.
@@ -80,7 +82,9 @@ struct ScriptCompression
         if (nSize < nSpecialScripts) {
             CompressedScript vch(GetSpecialScriptSize(nSize), 0x00);
             s >> std::span{vch};
-            DecompressScript(script, nSize, vch);
+            if (!DecompressScript(script, nSize, vch)) {
+                throw std::ios_base::failure("Non-decodable compressed script");
+            }
             return;
         }
         nSize -= nSpecialScripts;
diff --git a/src/test/compress_tests.cpp b/src/test/compress_tests.cpp
index 7fefa46744..eba72eb3be 100644
--- a/src/test/compress_tests.cpp
+++ b/src/test/compress_tests.cpp
@@ -3,11 +3,15 @@
 // file COPYING or http://www.opensource.org/licenses/mit-license.php.

 #include <compressor.h>
+#include <key.h>
 #include <script/script.h>
+#include <streams.h>
 #include <test/util/random.h>
 #include <test/util/setup_common.h>
+#include <test/util/common.h>

 #include <cstdint>
+#include <vector>

 #include <boost/test/unit_test.hpp>

@@ -161,6 +165,48 @@ BOOST_AUTO_TEST_CASE(compress_p2pk_scripts_not_on_curve)
         CScript uncompressed_script;
         bool success = DecompressScript(uncompressed_script, compression_id, compressed_script);
         BOOST_CHECK_EQUAL(success, false);
+
+        // The Unser path should throw an exception when it can't be decompressed. Otherwise,
+        // it will leave the script empty, which consensus-wise means anyone-can-spend,
+        // instead of being an unspendable off-curve P2PK script.
+        DataStream s = DataStream{} << VARINT(compression_id) << std::span{compressed_script};
+        CScript restored;
+        BOOST_CHECK_EXCEPTION(s >> Using<ScriptCompression>(restored), std::ios_base::failure, HasReason{"Non-decodable compressed script"});
+    }
+
+    // Check off-curve script serialization round-trips properly
+    DataStream s = DataStream{} << Using<ScriptCompression>(script);
+    CScript restored;
+    s >> Using<ScriptCompression>(restored);
+    BOOST_CHECK(restored == script);
+}
+
+BOOST_AUTO_TEST_CASE(compress_p2pk_wrong_y)
+{
+    // An uncompressed pubkey with a wrong Y for its X isn't on the curve, so such
+    // a P2PK is unspendable.
+    // Ensure it is stored raw and never encoded as 0x04/0x05. That encoding keeps X
+    // and only Y's parity, so it would decompress to the correct Y and make the
+    // script spendable, which would be bad.
+    for (int i = 0; i < 1000; ++i) {
+        CKey key = GenerateRandomKey(/*compressed=*/false);
+        std::vector<unsigned char> pub = ToByteVector(key.GetPubKey());
+        pub[33] ^= 0x01; // corrupt Y without changing its parity
+        assert(!CPubKey(pub).IsFullyValid());
+        CScript script = CScript() << pub << OP_CHECKSIG;
+        BOOST_CHECK_EQUAL(script.size(), 67U);
+
+        CompressedScript out;
+        bool done = CompressScript(script, out);
+        BOOST_CHECK_EQUAL(done, false);
+
+        // Ensure serialize stores it raw (1-byte size prefix + 67, not 33 compressed)
+        // and unserialize gives it back unchanged
+        DataStream s = DataStream{} << Using<ScriptCompression>(script);
+        BOOST_CHECK_EQUAL(s.size(), 68U);
+        CScript restored;
+        s >> Using<ScriptCompression>(restored);
+        BOOST_CHECK(restored == script);
     }
 }

diff --git a/src/test/fuzz/script.cpp b/src/test/fuzz/script.cpp
index 0017af380a..14ec0a10a3 100644
--- a/src/test/fuzz/script.cpp
+++ b/src/test/fuzz/script.cpp
@@ -94,13 +94,50 @@ FUZZ_TARGET(script, .init = initialize_script)
     (void)Solver(script, solutions);

     {
-        const std::vector<uint8_t> bytes = ConsumeRandomLengthByteVector(fuzzed_data_provider);
-        CompressedScript compressed_script;
-        compressed_script.assign(bytes.begin(), bytes.end());
-        // DecompressScript(..., ..., bytes) is not guaranteed to be defined if the bytes vector is too short
-        if (compressed_script.size() >= 32) {
+        // Exercises ScriptCompression::Unser path.
+        // First, this always runs inside a Coin record, so more data follows the script
+        // in the stream and it must not be consumed.
+        //
+        // A compressed script starts with its type: one of six special encodings (0 to 5) with
+        // a fixed-size payload, or a raw script length plus nSpecialScripts. A special script
+        // must decode to a non-empty script or throw, never turn into a different script.
+        // The rest of scripts either decode raw or as OP_RETURN for ones exceeding MAX_SCRIPT_SIZE.
+        unsigned int type;
+        unsigned int payload_size;
+        if (fuzzed_data_provider.ConsumeBool()) {
+            type = fuzzed_data_provider.ConsumeIntegralInRange<unsigned int>(0, ScriptCompression::nSpecialScripts - 1);
+            payload_size = GetSpecialScriptSize(type);
+        } else {
+            // For a script with length > MAX_SCRIPT_SIZE the script is replaced for an OP_RETURN
+            payload_size = fuzzed_data_provider.ConsumeIntegralInRange<unsigned int>(0, MAX_SCRIPT_SIZE + 16);
+            type = payload_size + ScriptCompression::nSpecialScripts;
+        }
+
+        const std::vector<uint8_t> payload = ConsumeFixedLengthByteVector(fuzzed_data_provider, payload_size);
+        const std::vector<std::byte> trailing = ConsumeRandomLengthByteVector<std::byte>(fuzzed_data_provider);
+        // Decodable unless it is a pubkey record (type 4 or 5) whose X coordinate is not a valid compressed pubkey.
+        bool decodable{true};
+        if (type == 4 || type == 5) {
+            std::vector<unsigned char> pubkey{static_cast<unsigned char>(type - 2)};
+            pubkey.insert(pubkey.end(), payload.begin(), payload.end());
+            decodable = CPubKey{pubkey}.IsFullyValid();
+        }
+
+        DataStream stream = DataStream{} << VARINT(type) << std::span{payload} << std::span{trailing};
+        try {
             CScript decompressed_script;
-            DecompressScript(decompressed_script, fuzzed_data_provider.ConsumeIntegral<unsigned int>(), compressed_script);
+            stream >> Using<ScriptCompression>(decompressed_script);
+            assert(decodable);
+            if (type < ScriptCompression::nSpecialScripts) {
+                assert(!decompressed_script.empty()); // future: check each type individually
+            } else if (payload_size > MAX_SCRIPT_SIZE) {
+                assert(decompressed_script == CScript() << OP_RETURN);
+            } else {
+                assert(decompressed_script == CScript(payload.begin(), payload.end()));
+            }
+            assert(std::ranges::equal(stream, trailing)); // only the script was consumed
+        } catch (const std::ios_base::failure&) {
+            assert(!decodable);
         }
     }


</patch>
